SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.EditProjects') IS NULL CREATE TABLE dbo.EditProjects(EditProjectId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL UNIQUE,GenerationPackageVersionId UNIQUEIDENTIFIER NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'NOT_STARTED',TargetDurationSeconds INT NULL,CurrentDurationSeconds DECIMAL(10,2) NULL,Resolution NVARCHAR(40) NOT NULL DEFAULT '3840x2160',FrameRate DECIMAL(6,3) NOT NULL DEFAULT 24,AspectRatio NVARCHAR(20) NOT NULL DEFAULT '16:9',AudioSampleRate INT NOT NULL DEFAULT 48000,ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,ApprovedMasterVersionId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_EditProjects_Workspaces FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId),CONSTRAINT FK_EditProjects_Projects FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId));
IF OBJECT_ID('dbo.EditTimelines') IS NULL CREATE TABLE dbo.EditTimelines(EditTimelineId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,EditProjectId UNIQUEIDENTIFIER NOT NULL,VersionNumber INT NOT NULL DEFAULT 1,Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',DurationSeconds DECIMAL(10,2) NULL,SettingsJson NVARCHAR(MAX) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_EditTimelines_EditProjects FOREIGN KEY(EditProjectId) REFERENCES dbo.EditProjects(EditProjectId));
IF OBJECT_ID('dbo.EditTimelineItems') IS NULL CREATE TABLE dbo.EditTimelineItems(EditTimelineItemId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,EditTimelineId UNIQUEIDENTIFIER NOT NULL,SceneId UNIQUEIDENTIFIER NULL,GeneratedAssetId UNIQUEIDENTIFIER NULL,TrackType NVARCHAR(30) NOT NULL,TrackNumber INT NOT NULL DEFAULT 1,SequenceOrder INT NOT NULL,StartTimeSeconds DECIMAL(10,3) NOT NULL,EndTimeSeconds DECIMAL(10,3) NOT NULL,SourceInSeconds DECIMAL(10,3) NOT NULL DEFAULT 0,SourceOutSeconds DECIMAL(10,3) NULL,TransitionIn NVARCHAR(120) NULL,TransitionOut NVARCHAR(120) NULL,VolumeDb DECIMAL(8,2) NULL,SpeedPercent DECIMAL(8,2) NOT NULL DEFAULT 100,SettingsJson NVARCHAR(MAX) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_EditTimelineItems_Timelines FOREIGN KEY(EditTimelineId) REFERENCES dbo.EditTimelines(EditTimelineId),CONSTRAINT FK_EditTimelineItems_Assets FOREIGN KEY(GeneratedAssetId) REFERENCES dbo.GeneratedAssets(GeneratedAssetId));
IF OBJECT_ID('dbo.EditInstructions') IS NULL CREATE TABLE dbo.EditInstructions(EditInstructionId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,EditProjectId UNIQUEIDENTIFIER NOT NULL,SceneId UNIQUEIDENTIFIER NULL,TimecodeSeconds DECIMAL(10,3) NULL,InstructionType NVARCHAR(40) NOT NULL,InstructionText NVARCHAR(MAX) NOT NULL,OwnerType NVARCHAR(60) NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'OPEN',Priority NVARCHAR(20) NOT NULL DEFAULT 'MEDIUM',CreatedByUserId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),ResolvedAt DATETIME2 NULL,CONSTRAINT FK_EditInstructions_EditProjects FOREIGN KEY(EditProjectId) REFERENCES dbo.EditProjects(EditProjectId));
IF OBJECT_ID('dbo.QAChecks') IS NULL CREATE TABLE dbo.QAChecks(QACheckId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,EditProjectId UNIQUEIDENTIFIER NOT NULL,CheckKey NVARCHAR(100) NOT NULL,Category NVARCHAR(60) NOT NULL,CheckName NVARCHAR(250) NOT NULL,Severity NVARCHAR(30) NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'NOT_RUN',Evidence NVARCHAR(MAX) NULL,IsBlocking BIT NOT NULL DEFAULT 0,Automated BIT NOT NULL DEFAULT 1,ResolvedByUserId UNIQUEIDENTIFIER NULL,ResolvedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_QAChecks_EditProjects FOREIGN KEY(EditProjectId) REFERENCES dbo.EditProjects(EditProjectId));
IF OBJECT_ID('dbo.MasterVideoVersions') IS NULL CREATE TABLE dbo.MasterVideoVersions(MasterVideoVersionId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,EditProjectId UNIQUEIDENTIFIER NOT NULL,EditTimelineId UNIQUEIDENTIFIER NULL,VersionNumber INT NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'DRAFT',StorageUri NVARCHAR(1000) NULL,ReviewUri NVARCHAR(1000) NULL,DurationSeconds DECIMAL(10,2) NULL,Resolution NVARCHAR(40) NULL,FrameRate DECIMAL(6,3) NULL,MimeType NVARCHAR(120) NULL,FileSizeBytes BIGINT NULL,QASummaryJson NVARCHAR(MAX) NULL,ChangeSummary NVARCHAR(2000) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,ReviewedByUserId UNIQUEIDENTIFIER NULL,ReviewedAt DATETIME2 NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_MasterVideoVersions_Workspaces FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId),CONSTRAINT FK_MasterVideoVersions_Projects FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId),CONSTRAINT FK_MasterVideoVersions_EditProjects FOREIGN KEY(EditProjectId) REFERENCES dbo.EditProjects(EditProjectId));
IF OBJECT_ID('dbo.MasterVideoReviews') IS NULL CREATE TABLE dbo.MasterVideoReviews(MasterVideoReviewId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,MasterVideoVersionId UNIQUEIDENTIFIER NOT NULL,Decision NVARCHAR(30) NOT NULL,Comment NVARCHAR(3000) NULL,DecidedByUserId UNIQUEIDENTIFIER NULL,DecidedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_MasterVideoReviews_Versions FOREIGN KEY(MasterVideoVersionId) REFERENCES dbo.MasterVideoVersions(MasterVideoVersionId));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_EditTimelineItems_TimelineTrack') CREATE INDEX IX_EditTimelineItems_TimelineTrack ON dbo.EditTimelineItems(EditTimelineId,TrackType,TrackNumber,SequenceOrder);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_QAChecks_EditProjectStatus') CREATE INDEX IX_QAChecks_EditProjectStatus ON dbo.QAChecks(EditProjectId,Status,Severity);
COMMIT;
